  const clone = await cloneRepo(sandbox, env, ref);
  if (!clone.success) {
    await sandbox.destroy();
    return {
      result: {
        runId,
        ref,
        commitSha: "",
        startedAt,
        completedAt: new Date().toISOString(),
        success: false,
        commands: [],
        error: `git clone failed: ${clone.output}`,
      },
      artifacts: {},
    };
  }

